INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('e01f8f74-61fe-4d25-b27d-72112e86ecd4', 'a1b2c3d4-2222-4000-8000-000000000002', 1, 'O que é Oração?', 'Redescubrindo o diálogo com Deus', '{"intro": "Santa Teresa de \u00c1vila definiu ora\u00e7\u00e3o como \"um trato de amizade com Aquele que sabemos que nos ama\". N\u00e3o \u00e9 uma f\u00f3rmula m\u00e1gica nem uma lista de pedidos \u2014 \u00e9 um relacionamento. Assim como qualquer amizade, exige tempo, presen\u00e7a e sinceridade. O Catecismo ensina que ora\u00e7\u00e3o \u00e9 a eleva\u00e7\u00e3o da alma a Deus (CIC 2559). Mas antes de elevar, precisamos reconhecer: somos amados antes de orar.", "prayer": "Senhor, ensina-me a rezar. Que eu descubra que antes de eu Te procurar, Tu j\u00e1 me encontraste. Am\u00e9m.", "practice": "Reserve 10 minutos hoje para simplesmente estar na presen\u00e7a de Deus. Sem pedir nada. Sem dizer nada. Apenas estar.", "scripture": "\"Eis que estou \u00e0 porta e bato. Se algu\u00e9m ouvir a minha voz e abrir a porta, entrarei em sua casa e cearei com ele, e ele comigo.\" \u2014 Ap 3,20", "reflection": "Se ora\u00e7\u00e3o \u00e9 amizade, como est\u00e1 sua amizade com Deus hoje? Voc\u00ea fala mais ou escuta mais?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;